def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    prev_bids = []
    opp_budgets = []
    opp_desperation = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(float(opp.get('budget', 0)))
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
                opp_desperation += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_opp_budget = max(opp_budgets) if opp_budgets else 0.0

    units = supply / float(WATER_REQ)
    tight = units < 2.0
    very_tight = units < 1.4
    loose = units >= 1.8

    critical = hp <= 3 or no_water_days >= 2
    urgent = hp <= 5 or no_water_days >= 1

    if critical:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2.0, avg_prev + 3.0)
        if very_tight:
            bid = max(bid, 1.02 * highest_prev + 2.0)
        bid = min(budget, bid)
        return float(max(0.0, bid))

    if urgent:
        if tight:
            bid = max(0.78 * DAILY_SALARY, highest_prev + 1.5)
        else:
            bid = max(0.62 * DAILY_SALARY, avg_prev * 0.72)
        if opp_desperation >= 2:
            bid += 4.0
        bid = min(budget, bid)
        return float(max(0.0, bid))

    if very_tight:
        bid = max(0.58 * DAILY_SALARY, highest_prev + 1.0)
        if highest_prev >= 100:
            bid = max(0.52 * DAILY_SALARY, avg_prev * 0.45)
    elif tight:
        if highest_prev >= 110:
            bid = max(24.0, avg_prev * 0.32)
        else:
            bid = max(30.0, highest_prev + 1.0)
    elif loose:
        bid = 18.0 if hp >= 7 else 24.0
        if highest_prev < 50 and day >= 7:
            bid = 28.0
    else:
        bid = max(22.0, avg_prev * 0.28)

    if budget < max_opp_budget * 0.35 and hp >= 6:
        bid *= 0.85

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    bid = min(budget, bid)
    return float(max(0.0, bid))
